<section class="page-banner compact"><div class="container page-banner-inner"><div><p class="eyebrow">TRANSACTIONS / HISTORY</p><h1>Every sale, accounted for.</h1><p class="lead">A record of what sold, who bought it, who served them, and when.</p></div><a class="button primary" href="<?= site_url('sales/new') ?>">Record sale <span aria-hidden="true">↗</span></a></div></section>
<section class="section listing-section"><div class="container">
    <div class="table-summary"><div><p class="eyebrow">SALES LEDGER</p><h2><?= count($sales) ?> transactions</h2></div></div>
    <?php if (session('notice')): ?><p class="notice" role="status"><?= esc(session('notice')) ?></p><?php endif; ?>
    <?php if ($sales === []): ?><div class="empty-state"><span class="empty-glyph" aria-hidden="true">↗</span><h3>History begins with a sale</h3><p>Record your first transaction to see the product, customer, staff member, quantity, and total here.</p><a class="button primary" href="<?= site_url('sales/new') ?>">Record a sale</a></div>
    <?php else: ?><div class="table-card"><table><thead><tr><th scope="col">Sale</th><th scope="col">Product</th><th scope="col">Customer</th><th scope="col">Staff</th><th scope="col">Quantity</th><th scope="col">Total</th><th scope="col">Date</th></tr></thead><tbody><?php foreach ($sales as $sale): ?><tr><td data-label="Sale"><strong>#<?= (int) $sale['id'] ?></strong></td><td data-label="Product"><?= esc($sale['product_name']) ?></td><td data-label="Customer"><?= $sale['customer_name'] === null ? '<span class="table-subtext">Walk-in</span>' : esc($sale['customer_name']) ?></td><td data-label="Staff"><?= esc($sale['staff_name']) ?></td><td data-label="Quantity"><?= (int) $sale['quantity'] ?></td><td data-label="Total"><strong><?= marketmate_money($sale['total_price']) ?></strong></td><td data-label="Date"><?= esc(date('M j, Y · g:i A', strtotime($sale['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
</div></section>
